import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
export default defineConfig({ plugins:[react()] })

import { useState } from 'react'
export default function App(){
  const [n,setN]=useState(0)
  return (<div className='min-h-screen flex flex-col items-center justify-center gap-4 bg-slate-50'>
    <h1 className='text-3xl font-bold text-indigo-600'>Hello from Grg Code</h1>
    <button className='px-4 py-2 rounded-lg bg-indigo-600 text-white' onClick={()=>setN(n+1)}>Count: {n}</button>
  </div>)
}
